python3 - <<'PY'
import json, urllib.request

base = 'http://127.0.0.1:8132'
with urllib.request.urlopen(base + '/audits/last') as r:
    last_doc = json.load(r)
last_seq = last_doc.get('last_seq')
if type(last_seq) is not int:
    raise SystemExit('invalid last_seq')
with urllib.request.urlopen(base + f'/inquiries?after={last_seq}') as r:
    inquiries = json.load(r)
if not isinstance(inquiries, list):
    raise SystemExit('invalid inquiries response')
if not inquiries:
    raise SystemExit(0)
for item in inquiries:
    if not isinstance(item, dict) or type(item.get('seq')) is not int or not isinstance(item.get('text'), str):
        raise SystemExit('invalid inquiry')

# Semantic review of every inquiry in this fetched batch: seq 24 says the customer
# is completely blocked from working; seq 29 disputes a $310 charge and asks for credit.
urgent_seqs = {24, 29}
fetched_seqs = {item['seq'] for item in inquiries}
if not urgent_seqs <= fetched_seqs:
    raise SystemExit('reviewed urgent sequence missing from fetched batch')
urgent_count = sum(item['seq'] in urgent_seqs for item in inquiries)
total_count = len(inquiries)
payload = {
    'batch_start_seq': min(item['seq'] for item in inquiries),
    'batch_end_seq': max(item['seq'] for item in inquiries),
    'urgent_count': urgent_count,
    'total_count': total_count,
    'urgent_fraction': round(urgent_count / total_count + 1e-12, 2),
}
expected_keys = {'batch_start_seq','batch_end_seq','urgent_count','total_count','urgent_fraction'}
if set(payload) != expected_keys:
    raise SystemExit('invalid keys')
if any(type(payload[k]) is not int for k in ('batch_start_seq','batch_end_seq','urgent_count','total_count')):
    raise SystemExit('non-integer count or boundary')
if payload['batch_start_seq'] != min(fetched_seqs) or payload['batch_end_seq'] != max(fetched_seqs):
    raise SystemExit('invalid batch boundaries')
if payload['total_count'] != len(inquiries) or not (0 <= payload['urgent_count'] <= payload['total_count']):
    raise SystemExit('invalid counts')
if payload['urgent_fraction'] != round(payload['urgent_count'] / payload['total_count'] + 1e-12, 2):
    raise SystemExit('invalid urgent fraction')
body = json.dumps(payload, separators=(',', ':')).encode()
req = urllib.request.Request(base + '/audits', data=body, headers={'Content-Type':'application/json'}, method='POST')
with urllib.request.urlopen(req) as r:
    if not 200 <= r.status < 300:
        raise SystemExit(f'POST failed: {r.status}')
PY
